params.command:
$ErrorActionPreference='Stop'
$repo = Join-Path $env:USERPROFILE 'HeavenBridgeRepo'
$tmp = Join-Path $env:USERPROFILE 'HeavenBridge\verify-main-1101'
git -C $repo fetch origin main
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$remoteSha = (git -C $repo rev-parse origin/main).Trim()
Write-Output "REMOTE_MAIN_SHA=$remoteSha"
if (Test-Path $tmp) {
  git -C $repo worktree remove --force $tmp 2>$null
  if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
}
git -C $repo worktree add --detach $tmp $remoteSha
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
try {
  $worker = Join-Path $tmp 'heaven-bridge\worker.py'
  $test1 = Join-Path $tmp 'heaven-bridge\test_worker.py'
  $test2 = Join-Path $tmp 'heaven-bridge\tests\test_worker.py'
  $bootstrap = Join-Path $tmp 'heaven-bridge\bootstrap.ps1'
  $manage = Join-Path $tmp 'heaven-bridge\manage.ps1'
  foreach ($p in @($worker,$test1,$test2,$bootstrap,$manage)) {
    if (-not (Test-Path -LiteralPath $p)) { throw "missing expected path: $p" }
  }
  python -m py_compile $worker
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
  python $test1
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
  python $test2
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
  [void][scriptblock]::Create((Get-Content -Raw -LiteralPath $bootstrap))
  [void][scriptblock]::Create((Get-Content -Raw -LiteralPath $manage))
  git -C $tmp diff --check
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
  Write-Output 'EXACT_MAIN_GATE_OK'
} finally {
  git -C $repo worktree remove --force $tmp 2>$null
}
